INSERT INTO alertas_auditoria (tipo, alerta, mensaje, severidad)
VALUES ('datos', 'A2', $1, 'critica')
RETURNING id, 'Consulta bloqueada: no se ejecutó nada en la base de datos.' || E'\n\n' || mensaje AS respuesta;
